/* ============================================
   MENTION COMPONENT
   A reference written into a sentence, and the menu a trigger opens:
   `@` for entities, `/` for skills.
   ============================================ */

/* ============================================
   TAG
   Composer lays this exact tag over the text of its textarea, so nothing
   here may move a glyph off its advance: no weight, no spacing, and a
   chip whose padding is paid back in margin.
   ============================================ */

.ds-mention {
  /* How far the chip's fill reaches past the glyphs on each side. Padding
     out, margin back in: the box grows and the text does not move. */
  --ds-mention-bleed: var(--padding-050);
  margin: 0 calc(-1 * var(--ds-mention-bleed));
  padding: 0 var(--ds-mention-bleed);
  /* The theme's action colour in its text form, the tone a tertiary button
     writes its label in. A mention is the one word in a sentence that was
     chosen from a menu and points at something, so it wears the colour that
     means "this does something", and it moves with the theme where a fixed
     hue blended into the themes built near it. Behind it, a wash of the
     same tone, barely there: enough to give the tag an edge, never enough
     to read as a chip sitting on the line. The wash carries the tag in a
     theme whose action colour is a neutral. */
  background-color: var(
    --ds-mention-bg,
    color-mix(in srgb, var(--color-action-primary-text-tertiary) 10%, transparent)
  );
  border-radius: var(--radius-100);
  /* A name that wraps keeps its fill and corners on both lines */
  box-decoration-break: clone;
  /* Two parts in five of the body colour are mixed in. A button label is
     large and bold enough to carry an action colour that sits near the
     page; a name set in running text is not, and unmixed it fell under
     3:1 in the themes whose action colour is closest to their surface.
     At this ratio it clears 4.5:1 on the page in every shipped theme and
     both modes, and still reads as the action colour. */
  color: var(
    --ds-mention-color,
    color-mix(in srgb, var(--color-action-primary-text-tertiary) 60%, var(--color-text-primary))
  );
}

/* The trigger is punctuation; the name is the word */
.ds-mention__trigger {
  opacity: 0.64;
}

/* ============================================
   MENU
   The floating-surface recipe the chat set's other menus use.
   ============================================ */

.ds-mention-menu {
  box-sizing: border-box;
  /* Consumer hooks: how wide the menu is, and how many rows show before
     the list scrolls */
  width: var(--ds-mention-menu-width, 320px);
  max-width: 100%;
  /* Page background, not container: the container fill is semi-transparent
     in dark mode, and a floating panel must not show text through itself */
  background-color: var(--color-bg-page-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-300);
  box-shadow: var(--shadow-floating);
  overflow: hidden;
  animation: ds-mention-menu-appear var(--motion-duration-fast) var(--motion-ease-entrance);
}

@keyframes ds-mention-menu-appear {
  from {
    opacity: 0;
  }
}

.ds-mention-menu__list {
  /* Anchors each row's offsetTop, which is how the highlighted row is kept
     in view */
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  padding: var(--padding-100);
  /* Rows × (one line, its block padding, and the gap under it), plus half a
     row more, so a longer list is cut mid-row and reads as scrollable */
  max-height: calc(
    (var(--ds-mention-menu-max-rows, 8) + 0.5) *
      (var(--font-paragraph-sm-line-height) + 2 * var(--padding-150) + var(--gap-050)) +
      var(--padding-100)
  );
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--color-bg-container-secondary) transparent;
}

.ds-mention-menu__list:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
  border-radius: var(--radius-300);
}

/* ============================================
   OPTION
   ============================================ */

.ds-mention-menu__option {
  display: flex;
  align-items: center;
  flex: none;
  gap: var(--gap-200);
  padding: var(--padding-150) var(--padding-200);
  border-radius: var(--radius-200);
  cursor: pointer;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-primary);
}

/* One highlight, shared by the pointer and the arrow keys: the pointer
   moves it rather than drawing a second one. DropdownMenu's focused wash,
   a translucent neutral, because it is the only sign of where Enter will
   land and an opaque surface step can equal the panel's own fill in a
   theme that flattens the two. */
.ds-mention-menu__option--active {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-mention-menu__option--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-mention-menu__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  /* The row's own line box, so an icon never makes its row taller than a
     row without one */
  height: var(--font-paragraph-sm-line-height);
  color: var(--color-icon-secondary);
}

.ds-mention-menu__icon .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-mention-menu__label {
  flex: none;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* While a query narrows the list, the typed part of each name holds full
   strength and the rest steps back. Colour carries it as well as weight,
   because a theme may set both paragraph weights the same. */
.ds-mention-menu--filtered .ds-mention-menu__label {
  color: var(--color-text-secondary);
}

.ds-mention-menu__match {
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  color: var(--color-text-primary);
}

.ds-mention-menu__description {
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--color-text-tertiary);
}

/* ============================================
   EMPTY
   ============================================ */

.ds-mention-menu__empty {
  padding: var(--padding-300) var(--padding-400);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

'use client';

import React, { useLayoutEffect, useRef } from 'react';
import '../../fonts/material-symbols.css';
import './Mention.css';
import { mentionListboxId, mentionOptionId, splitMentions } from './mentions';
import type { MentionItem, MentionSource } from './mentions';

/* The data shapes and helpers live in a React-free module with a subpath
   of its own (`rift-ds/components/Mention/mentions`), so a Server Component
   or a route handler can run them without crossing this file's client
   boundary. They are re-exported here as well, because this file is what
   the package barrel resolves to. A star, deliberately: the docs parser
   that builds the props tables drops this module's first component when
   the same names are re-exported one by one. */
// eslint-disable-next-line react-refresh/only-export-components
export * from './mentions';

/* ============================================
   MENTION — the inline tag
   ============================================ */

type MentionOwnProps = {
  /** The character that opened the mention, drawn a step quieter than the name. */
  trigger?: string;
  /** Additional CSS classes */
  className?: string;
  /** The name: a person, a file, a skill. */
  children?: React.ReactNode;
};

export interface MentionProps
  extends MentionOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof MentionOwnProps> {}

/**
 * Mention is a reference written into a sentence: `@` and a name for an
 * entity, `/` and a name for a skill. It is colour and nothing else, with
 * no padding, fill or weight of its own, so the same tag reads correctly
 * inside a message and can be laid exactly over the text of an input while
 * it is being typed.
 */
export const Mention = React.forwardRef<HTMLSpanElement, MentionProps>(
  ({ trigger = '@', className = '', children, ...rest }, ref) => (
    <span
      {...rest}
      ref={ref}
      className={['ds-mention', className].filter(Boolean).join(' ')}
      data-trigger={trigger}
    >
      <span className="ds-mention__trigger">{trigger}</span>
      {children}
    </span>
  ),
);

Mention.displayName = 'Mention';

/* ============================================
   MENTION TEXT — a string with its mentions drawn
   ============================================ */

type MentionTextOwnProps = {
  /** The plain text, exactly as it was typed or sent. */
  text: string;
  /** The sources whose items count as mentions in this text. */
  sources: MentionSource[];
  /** Additional CSS classes */
  className?: string;
};

export interface MentionTextProps
  extends MentionTextOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof MentionTextOwnProps | 'children'> {}

/**
 * MentionText draws a plain string with every mention in it as a Mention
 * tag: the sent half of the pattern, for a message that was typed with
 * mentions in it. The text is the only record. Nothing else needs storing.
 */
export const MentionText = React.forwardRef<HTMLSpanElement, MentionTextProps>(
  ({ text, sources, className = '', ...rest }, ref) => (
    <span
      {...rest}
      ref={ref}
      className={['ds-mention-text', className].filter(Boolean).join(' ')}
    >
      {splitMentions(text, sources).map((segment, index) =>
        segment.type === 'mention' ? (
          // Segments never reorder: the text is re-split whole on every change
          <Mention key={index} trigger={segment.trigger}>
            {segment.item.label}
          </Mention>
        ) : (
          <React.Fragment key={index}>{segment.text}</React.Fragment>
        ),
      )}
    </span>
  ),
);

MentionText.displayName = 'MentionText';

/* ============================================
   MENTION MENU — the list a trigger opens
   ============================================ */

type MentionMenuOwnProps = {
  /** The items to list, already filtered and ordered. */
  items: MentionItem[];
  /** The `id` of the highlighted item: the one Enter would choose. */
  activeId?: string;
  /** Fires with an item's `id` when the pointer moves onto it. */
  onActiveChange?: (id: string) => void;
  /** Fires with the item a person chose. */
  onSelect?: (item: MentionItem) => void;
  /** The text typed so far. The part of each label that matches it is drawn stronger. */
  query?: string;
  /** Accessible name for the list. */
  label?: string;
  /** Shown in place of the list when `items` is empty. Without it an empty menu renders nothing. */
  emptyText?: React.ReactNode;
  /** Additional CSS classes */
  className?: string;
};

export interface MentionMenuProps
  extends MentionMenuOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof MentionMenuOwnProps | 'children'> {}

const renderLabel = (label: string, query: string) => {
  const needle = query.trim().toLowerCase();
  const at = needle === '' ? -1 : label.toLowerCase().indexOf(needle);
  if (at < 0) return label;
  return (
    <>
      {label.slice(0, at)}
      <span className="ds-mention-menu__match">{label.slice(at, at + needle.length)}</span>
      {label.slice(at + needle.length)}
    </>
  );
};

/**
 * MentionMenu is the list a trigger character opens. It never takes focus:
 * the caret stays in the field the person is typing in, which owns the
 * arrow keys and points `aria-activedescendant` at the highlighted row
 * (`mentionOptionId` builds the id). The menu draws the rows, follows the
 * pointer, and reports a choice.
 *
 * Composer wires all of this itself through its `mentions` prop. Reach for
 * MentionMenu directly to build the pattern on another field.
 */
export const MentionMenu = React.forwardRef<HTMLDivElement, MentionMenuProps>(
  (
    {
      items,
      activeId,
      onActiveChange,
      onSelect,
      query = '',
      label = 'Suggestions',
      emptyText,
      className = '',
      id,
      onMouseDown,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-mention-menu';
    const generatedId = React.useId();
    const menuId = id ?? generatedId;
    const listRef = useRef<HTMLDivElement | null>(null);

    /* Keep the highlighted row in view by moving the list alone. scrollIntoView
       would walk every scrollable ancestor and could shift the page under a
       person who is only pressing an arrow key. */
    useLayoutEffect(() => {
      const list = listRef.current;
      if (!list || activeId === undefined) return;
      const row = list.querySelector<HTMLElement>('[aria-selected="true"]');
      if (!row) return;
      const top = row.offsetTop;
      const bottom = top + row.offsetHeight;
      if (top < list.scrollTop) list.scrollTop = top;
      else if (bottom > list.scrollTop + list.clientHeight) {
        list.scrollTop = bottom - list.clientHeight;
      }
    }, [activeId, items]);

    if (items.length === 0 && !emptyText) return null;

    /* A press on the menu must not blur the field it serves: focus leaving
       is what closes the menu, and the click would land on nothing. */
    const handleMouseDown = (event: React.MouseEvent<HTMLDivElement>) => {
      onMouseDown?.(event);
      event.preventDefault();
    };

    return (
      <div
        {...rest}
        ref={ref}
        id={menuId}
        className={[baseClass, query.trim() !== '' ? `${baseClass}--filtered` : '', className]
          .filter(Boolean)
          .join(' ')}
        onMouseDown={handleMouseDown}
      >
        {items.length === 0 ? (
          <div className={`${baseClass}__empty`} role="status">
            {emptyText}
          </div>
        ) : (
          <div
            ref={listRef}
            id={mentionListboxId(menuId)}
            className={`${baseClass}__list`}
            role="listbox"
            aria-label={label}
            /* A region that can scroll has to be reachable from the keyboard
               on its own terms. In normal use the field owns the keys and
               takes Tab as "choose", so this stop is only ever met by
               someone who went looking for it. */
            tabIndex={0}
          >
            {items.map((item) => {
              const active = item.id === activeId;
              return (
                <div
                  key={item.id}
                  id={mentionOptionId(menuId, item.id)}
                  className={[
                    `${baseClass}__option`,
                    active ? `${baseClass}__option--active` : '',
                    item.disabled ? `${baseClass}__option--disabled` : '',
                  ]
                    .filter(Boolean)
                    .join(' ')}
                  role="option"
                  aria-selected={active}
                  aria-disabled={item.disabled || undefined}
                  /* Move, not enter: a list scrolling under a resting pointer
                     must not steal the highlight from the arrow keys */
                  onMouseMove={
                    item.disabled || active ? undefined : () => onActiveChange?.(item.id)
                  }
                  onClick={item.disabled ? undefined : () => onSelect?.(item)}
                >
                  {item.icon !== undefined && (
                    <span className={`${baseClass}__icon`} aria-hidden="true">
                      {typeof item.icon === 'string' ? (
                        <span className="material-symbols-rounded">{item.icon}</span>
                      ) : (
                        item.icon
                      )}
                    </span>
                  )}
                  <span className={`${baseClass}__label`}>{renderLabel(item.label, query)}</span>
                  {item.description && (
                    <span className={`${baseClass}__description`}>{item.description}</span>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    );
  },
);

MentionMenu.displayName = 'MentionMenu';

import type React from 'react';

/* The mention pattern's data shapes and its pure helpers. No React runtime
   in this module: a host can run these on a server, in a reducer, or in a
   test. Mention.tsx re-exports all of it. */

/* ============================================
   DATA SHAPES
   ============================================ */

/** One thing a person can reference: a teammate, a file, a skill. */
export type MentionItem = {
  /** Stable identity, unique within its source. */
  id: string;
  /** The name shown in the menu and written into the text after the trigger character. */
  label: string;
  /** A quieter second phrase on the same row: a role, a path, what a skill does. */
  description?: string;
  /** Leading mark: a Material Symbol name, or any node (an Avatar). Decorative. */
  icon?: string | React.ReactNode;
  /** Extra words the filter matches on besides the label. */
  keywords?: string[];
  /** Listed but not choosable. */
  disabled?: boolean;
};

/** Everything one trigger character opens: `@` for entities, `/` for skills. */
export type MentionSource = {
  /** The single character that opens this source. */
  trigger: string;
  /** The items it offers. */
  items: MentionItem[];
  /** Accessible name for this source's menu ("People", "Skills"). */
  label?: string;
};

/** A trigger being typed: where it starts, and what has been typed after it. */
export type MentionQuery = {
  /** The trigger character that opened it. */
  trigger: string;
  /** The text typed after the trigger, up to the caret. */
  query: string;
  /** Index of the trigger character. */
  start: number;
  /** Index of the caret. */
  end: number;
};

/** One run of text from `splitMentions`: plain words, or a recognised mention. */
export type MentionSegment =
  | { type: 'text'; text: string }
  | { type: 'mention'; text: string; trigger: string; item: MentionItem };

/* ============================================
   PURE HELPERS
   No React in these: a host can run them on a server, in a reducer, or in
   a test.
   ============================================ */

/** A query longer than this is prose that happens to follow a trigger, not a lookup. */
const MAX_QUERY_LENGTH = 48;

const isSpace = (char: string | undefined) => char === undefined || /\s/.test(char);

/**
 * Reads the mention being typed at the caret, if there is one: a trigger
 * character that opens a word, followed by no whitespace up to the caret.
 * A trigger in the middle of a word (the slash in a path, the at-sign in an
 * address) opens nothing.
 */
export function getMentionQuery(
  text: string,
  caret: number,
  triggers: string[],
): MentionQuery | null {
  for (let index = caret - 1; index >= 0 && caret - index <= MAX_QUERY_LENGTH + 1; index -= 1) {
    const char = text[index];
    if (isSpace(char)) return null;
    if (triggers.includes(char) && isSpace(text[index - 1])) {
      return { trigger: char, query: text.slice(index + 1, caret), start: index, end: caret };
    }
  }
  return null;
}

/**
 * Narrows and ranks a source's items for a query: labels that start with it
 * first, then labels where a later word starts with it, then labels that
 * contain it, then keyword matches. An empty query returns every item in its
 * given order.
 */
export function filterMentionItems(items: MentionItem[], query: string): MentionItem[] {
  const needle = query.trim().toLowerCase();
  if (needle === '') return items;
  const rank = (item: MentionItem) => {
    const label = item.label.toLowerCase();
    if (label.startsWith(needle)) return 0;
    if (label.split(/[\s\-_:./]+/).some((word) => word.startsWith(needle))) return 1;
    if (label.includes(needle)) return 2;
    if (item.keywords?.some((keyword) => keyword.toLowerCase().includes(needle))) return 3;
    return -1;
  };
  return items
    .map((item, index) => ({ item, index, rank: rank(item) }))
    .filter((entry) => entry.rank >= 0)
    .sort((a, b) => a.rank - b.rank || a.index - b.index)
    .map((entry) => entry.item);
}

/** Characters a mention may directly follow, besides whitespace and the start of the text. */
const OPENERS = new Set(['(', '[', '{', '"', '“', '‘', "'"]);

/** A mention ends where its label ends: the next character cannot continue a name. */
const continuesName = (char: string | undefined) =>
  char !== undefined && /[\p{L}\p{N}_-]/u.test(char);

/**
 * Splits text into plain runs and the mentions it contains. A mention is a
 * trigger character followed by the exact label of one of that source's
 * items, standing as its own word. Nothing is stored alongside the text: a
 * mention is recognised wherever its name is written, and stops being one
 * the moment the name is edited.
 */
export function splitMentions(text: string, sources: MentionSource[]): MentionSegment[] {
  const candidates = sources
    .flatMap((source) =>
      source.items.map((item) => ({
        trigger: source.trigger,
        item,
        token: `${source.trigger}${item.label}`,
      })),
    )
    // Longest first, so a name that begins with a shorter name wins its own match
    .sort((a, b) => b.token.length - a.token.length);
  const triggers = new Set(sources.map((source) => source.trigger));

  const segments: MentionSegment[] = [];
  let plainFrom = 0;
  let index = 0;
  while (index < text.length) {
    const before = text[index - 1];
    if (triggers.has(text[index]) && (isSpace(before) || OPENERS.has(before as string))) {
      const match = candidates.find(
        (candidate) =>
          text.startsWith(candidate.token, index) &&
          !continuesName(text[index + candidate.token.length]),
      );
      if (match) {
        if (index > plainFrom) segments.push({ type: 'text', text: text.slice(plainFrom, index) });
        segments.push({
          type: 'mention',
          text: match.token,
          trigger: match.trigger,
          item: match.item,
        });
        index += match.token.length;
        plainFrom = index;
        continue;
      }
    }
    index += 1;
  }
  if (plainFrom < text.length) segments.push({ type: 'text', text: text.slice(plainFrom) });
  return segments;
}

/**
 * Writes a chosen item over the query being typed: the trigger, the label,
 * and one trailing space, so the next word starts clean. Returns the new
 * text and where the caret belongs in it.
 */
export function insertMention(
  text: string,
  query: Pick<MentionQuery, 'trigger' | 'start' | 'end'>,
  item: MentionItem,
): { value: string; caret: number } {
  const before = text.slice(0, query.start);
  const after = text.slice(query.end);
  const token = `${query.trigger}${item.label}`;
  // A space is already waiting when the mention is written mid-sentence
  const spacer = after.startsWith(' ') ? '' : ' ';
  return {
    value: `${before}${token}${spacer}${after}`,
    caret: before.length + token.length + 1,
  };
}

/** The DOM id of one option inside a MentionMenu, for `aria-activedescendant`. */
export const mentionOptionId = (menuId: string, itemId: string) => `${menuId}-option-${itemId}`;

/** The DOM id of the listbox inside a MentionMenu, for `aria-controls`. */
export const mentionListboxId = (menuId: string) => `${menuId}-listbox`;
